type BackoffConfig struct {
	// BaseDelay is the amount of time to wait before retrying after the first
	// failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each retry.
	Multiplier float64
	// Jitter provides a range to randomize backoff delays.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

type Exponential struct {
	// BaseDelay is the amount of time to wait before retrying after the first
	// failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each retry.
	Multiplier float64
	// Jitter provides a range to randomize backoff delays.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

func (bc Exponential) Backoff(retries int) time.Duration {
	baseDelayValue := bc.BaseDelay
	if baseDelayValue <= 0 {
		baseDelayValue = baseDelay
	}
	multiplier := bc.Multiplier
	if multiplier <= 0 {
		multiplier = factor
	}
	jitterValue := bc.Jitter
	if bc.BaseDelay == 0 && bc.Multiplier == 0 && bc.Jitter == 0 {
		jitterValue = jitter
	}
	backoff, max := float64(baseDelayValue), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= multiplier
		retries--
	}
	if backoff > max {
		backoff = max
	}
	backoff *= 1 + jitterValue*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

var DefaultBackoffConfig = BackoffConfig{
	BaseDelay: 1 * time.Second,
	Multiplier: 1.6,
	Jitter: 0.2,
	MaxDelay: 120 * time.Second,
}

func WithBackoffConfig(b BackoffConfig) DialOption {
	return withBackoff(backoff.Exponential{
		BaseDelay: b.BaseDelay,
		Multiplier: b.Multiplier,
		Jitter: b.Jitter,
		MaxDelay: b.MaxDelay,
	})
}

func WithBackoffMaxDelay(md time.Duration) DialOption {
	return WithBackoffConfig(BackoffConfig{MaxDelay: md})
}

